-- Exact existing-owner counterpart; derived postcondition must pass actual SQL.
-- Proposed additive R008 repair, derived only from the frozen current309 evidence.
-- Historical migrations/canonical files are untouched. This is not a release approval.
-- Exact product change: relation CREATE TABLE renderer orders by pg_attribute.attnum.
-- Rebind only 238 changed relation definitions and the one existing renderer alias.
-- All 240 relations must match exact prior tuples AND contiguous live physical columns.
-- Two custodial_release_identity ordinal lists are source-derived expectations: they
-- MUST be confirmed by the live pg_attribute guard below, not treated as measured.
-- Captured timestamps change only for these 239 deliberately rebound inventory rows.
BEGIN;
DO $production_forward_original_owner$
BEGIN
 IF current_user<>'postgres' OR session_user<>current_user
  OR current_setting('custodial.deployment_project_ref',true) IS DISTINCT FROM 'rqquvtjdmugpigbndmne'
  OR current_setting('session_replication_role')<>'origin'
  OR current_setting('transaction_read_only')<>'off'
  OR NOT EXISTS(SELECT 1 FROM pg_roles WHERE rolname='postgres' AND NOT rolsuper AND rolbypassrls)
  OR NOT EXISTS(SELECT 1 FROM pg_class WHERE oid=to_regclass('public.custodial_release_authority_restore_inventory')
   AND relowner='postgres'::regrole AND relkind='r' AND relpersistence='p')
 THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Exact production postgres original owner/project/normal mutation context required';END IF;
END $production_forward_original_owner$;
SET LOCAL lock_timeout='5s';
SET LOCAL statement_timeout='120s';
SET LOCAL search_path=pg_catalog,public;
LOCK TABLE public.custodial_release_authority_restore_inventory IN ACCESS EXCLUSIVE MODE;
CREATE TEMP TABLE q310_expected_relations(
 identity text PRIMARY KEY,restore_order integer NOT NULL,old_sha256 text NOT NULL,
 new_sha256 text NOT NULL,needs_update boolean NOT NULL,columns_in_order text[] NOT NULL
) ON COMMIT DROP;
DO $predecessor$
DECLARE actual text; obj record; relation_oid oid; names text[]; ordinals integer[]; dropped boolean;
BEGIN
 IF current_user IS DISTINCT FROM session_user OR current_user NOT IN('postgres','supabase_admin') THEN
  RAISE EXCEPTION 'Maintained migration owner required';END IF;
 IF (SELECT count(*) FROM public.custodial_release_authority_restore_inventory)<>7700 THEN
  RAISE EXCEPTION 'Exact current309 inventory count required';END IF;
 SELECT public.static_weekly_digest_text(string_agg(restore_order::text||E'\n'||object_kind||E'\n'||object_identity||E'\n'||definition_sha256||E'\n'||public.static_weekly_digest_text(definition_sql),E'\n---\n' ORDER BY object_kind COLLATE "C",object_identity COLLATE "C"))
 INTO actual FROM public.custodial_release_authority_restore_inventory;
 IF actual IS DISTINCT FROM '3ad9148af807267bbf0ea00b893a720b760114244b92c97f6d76ea1805f77e8f' THEN RAISE EXCEPTION 'Exact frozen current309 inventory predecessor differs';END IF;
 IF public.static_weekly_digest_text(pg_get_functiondef('public.custodial_release_authority_current_relation_definition(text)'::regprocedure))
  IS DISTINCT FROM 'a9f77828c5917b95f5dea85ee46bed6ef6581e203cb468a7f15647b59fd7f125' THEN RAISE EXCEPTION 'Exact old relation renderer differs';END IF;
 IF public.static_weekly_digest_text(pg_get_functiondef('public.custodial_release_canary_authority_surface()'::regprocedure))
  IS DISTINCT FROM '55fe3e609c8a145f946602c6fbf16df4aa1eab410f50e048b778e7f4bfe72b33' THEN RAISE EXCEPTION 'Exact original canary function differs';END IF;
 SELECT public.static_weekly_digest_text(string_agg(object_kind||E'\n'||object_identity||E'\n'||purpose,E'\n---\n' ORDER BY object_kind COLLATE "C",object_identity COLLATE "C",purpose COLLATE "C"))
 INTO actual FROM public.custodial_release_canary_authority_surface();
 IF actual IS DISTINCT FROM '5fb9e516db6c710a84ab1d1d3c44c67ed06173feafbcc3f8e1c2436ea3a05e70' OR (SELECT count(*) FROM public.custodial_release_canary_authority_surface())<>1727 THEN
  RAISE EXCEPTION 'Exact original canary surface differs';END IF;
 IF (SELECT tgenabled FROM pg_trigger WHERE tgrelid='public.custodial_release_authority_restore_inventory'::regclass
  AND tgname='trg_custodial_release_authority_restore_inventory_immutable') IS DISTINCT FROM 'A' THEN
  RAISE EXCEPTION 'Original ALWAYS recovery guard required';END IF;
 -- Existing-owner profile: compare the complete measured 44 API default ACL
 -- rows. Do not grant, revoke, or replace the original platform defaults.
 IF (SELECT jsonb_agg(to_jsonb(q) ORDER BY owner_name COLLATE "C",schema_name COLLATE "C",object_type COLLATE "C",grantee COLLATE "C",grantor COLLATE "C",privilege_type COLLATE "C",is_grantable) FROM (
  SELECT r.rolname owner_name,CASE WHEN d.defaclnamespace=0 THEN '' ELSE n.nspname END schema_name,d.defaclobjtype::text object_type,
   coalesce(g.rolname,'PUBLIC') grantee,grantor.rolname grantor,a.privilege_type,a.is_grantable
  FROM pg_default_acl d JOIN pg_roles r ON r.oid=d.defaclrole LEFT JOIN pg_namespace n ON n.oid=d.defaclnamespace
  CROSS JOIN LATERAL aclexplode(d.defaclacl) a LEFT JOIN pg_roles g ON g.oid=a.grantee LEFT JOIN pg_roles grantor ON grantor.oid=a.grantor
  WHERE d.defaclnamespace IN(0,'public'::regnamespace) AND d.defaclobjtype IN('r','S')
   AND a.grantee IN(0,'anon'::regrole,'authenticated'::regrole,'service_role'::regrole)
 ) q) IS DISTINCT FROM $existing_defaults$[{"owner_name":"postgres","schema_name":"public","object_type":"S","grantee":"service_role","grantor":"postgres","privilege_type":"SELECT","is_grantable":false},{"owner_name":"postgres","schema_name":"public","object_type":"S","grantee":"service_role","grantor":"postgres","privilege_type":"UPDATE","is_grantable":false},{"owner_name":"postgres","schema_name":"public","object_type":"S","grantee":"service_role","grantor":"postgres","privilege_type":"USAGE","is_grantable":false},{"owner_name":"postgres","schema_name":"public","object_type":"r","grantee":"service_role","grantor":"postgres","privilege_type":"DELETE","is_grantable":false},{"owner_name":"postgres","schema_name":"public","object_type":"r","grantee":"service_role","grantor":"postgres","privilege_type":"INSERT","is_grantable":false},{"owner_name":"postgres","schema_name":"public","object_type":"r","grantee":"service_role","grantor":"postgres","privilege_type":"MAINTAIN","is_grantable":false},{"owner_name":"postgres","schema_name":"public","object_type":"r","grantee":"service_role","grantor":"postgres","privilege_type":"REFERENCES","is_grantable":false},{"owner_name":"postgres","schema_name":"public","object_type":"r","grantee":"service_role","grantor":"postgres","privilege_type":"SELECT","is_grantable":false},{"owner_name":"postgres","schema_name":"public","object_type":"r","grantee":"service_role","grantor":"postgres","privilege_type":"TRIGGER","is_grantable":false},{"owner_name":"postgres","schema_name":"public","object_type":"r","grantee":"service_role","grantor":"postgres","privilege_type":"TRUNCATE","is_grantable":false},{"owner_name":"postgres","schema_name":"public","object_type":"r","grantee":"service_role","grantor":"postgres","privilege_type":"UPDATE","is_grantable":false},{"owner_name":"supabase_admin","schema_name":"public","object_type":"S","grantee":"anon","grantor":"supabase_admin","privilege_type":"SELECT","is_grantable":false},{"owner_name":"supabase_admin","schema_name":"public","object_type":"S","grantee":"anon","grantor":"supabase_admin","privilege_type":"UPDATE","is_grantable":false},{"owner_name":"supabase_admin","schema_name":"public","object_type":"S","grantee":"anon","grantor":"supabase_admin","privilege_type":"USAGE","is_grantable":false},{"owner_name":"supabase_admin","schema_name":"public","object_type":"S","grantee":"authenticated","grantor":"supabase_admin","privilege_type":"SELECT","is_grantable":false},{"owner_name":"supabase_admin","schema_name":"public","object_type":"S","grantee":"authenticated","grantor":"supabase_admin","privilege_type":"UPDATE","is_grantable":false},{"owner_name":"supabase_admin","schema_name":"public","object_type":"S","grantee":"authenticated","grantor":"supabase_admin","privilege_type":"USAGE","is_grantable":false},{"owner_name":"supabase_admin","schema_name":"public","object_type":"S","grantee":"service_role","grantor":"supabase_admin","privilege_type":"SELECT","is_grantable":false},{"owner_name":"supabase_admin","schema_name":"public","object_type":"S","grantee":"service_role","grantor":"supabase_admin","privilege_type":"UPDATE","is_grantable":false},{"owner_name":"supabase_admin","schema_name":"public","object_type":"S","grantee":"service_role","grantor":"supabase_admin","privilege_type":"USAGE","is_grantable":false},{"owner_name":"supabase_admin","schema_name":"public","object_type":"r","grantee":"anon","grantor":"supabase_admin","privilege_type":"DELETE","is_grantable":false},{"owner_name":"supabase_admin","schema_name":"public","object_type":"r","grantee":"anon","grantor":"supabase_admin","privilege_type":"INSERT","is_grantable":false},{"owner_name":"supabase_admin","schema_name":"public","object_type":"r","grantee":"anon","grantor":"supabase_admin","privilege_type":"MAINTAIN","is_grantable":false},{"owner_name":"supabase_admin","schema_name":"public","object_type":"r","grantee":"anon","grantor":"supabase_admin","privilege_type":"REFERENCES","is_grantable":false},{"owner_name":"supabase_admin","schema_name":"public","object_type":"r","grantee":"anon","grantor":"supabase_admin","privilege_type":"SELECT","is_grantable":false},{"owner_name":"supabase_admin","schema_name":"public","object_type":"r","grantee":"anon","grantor":"supabase_admin","privilege_type":"TRIGGER","is_grantable":false},{"owner_name":"supabase_admin","schema_name":"public","object_type":"r","grantee":"anon","grantor":"supabase_admin","privilege_type":"TRUNCATE","is_grantable":false},{"owner_name":"supabase_admin","schema_name":"public","object_type":"r","grantee":"anon","grantor":"supabase_admin","privilege_type":"UPDATE","is_grantable":false},{"owner_name":"supabase_admin","schema_name":"public","object_type":"r","grantee":"authenticated","grantor":"supabase_admin","privilege_type":"DELETE","is_grantable":false},{"owner_name":"supabase_admin","schema_name":"public","object_type":"r","grantee":"authenticated","grantor":"supabase_admin","privilege_type":"INSERT","is_grantable":false},{"owner_name":"supabase_admin","schema_name":"public","object_type":"r","grantee":"authenticated","grantor":"supabase_admin","privilege_type":"MAINTAIN","is_grantable":false},{"owner_name":"supabase_admin","schema_name":"public","object_type":"r","grantee":"authenticated","grantor":"supabase_admin","privilege_type":"REFERENCES","is_grantable":false},{"owner_name":"supabase_admin","schema_name":"public","object_type":"r","grantee":"authenticated","grantor":"supabase_admin","privilege_type":"SELECT","is_grantable":false},{"owner_name":"supabase_admin","schema_name":"public","object_type":"r","grantee":"authenticated","grantor":"supabase_admin","privilege_type":"TRIGGER","is_grantable":false},{"owner_name":"supabase_admin","schema_name":"public","object_type":"r","grantee":"authenticated","grantor":"supabase_admin","privilege_type":"TRUNCATE","is_grantable":false},{"owner_name":"supabase_admin","schema_name":"public","object_type":"r","grantee":"authenticated","grantor":"supabase_admin","privilege_type":"UPDATE","is_grantable":false},{"owner_name":"supabase_admin","schema_name":"public","object_type":"r","grantee":"service_role","grantor":"supabase_admin","privilege_type":"DELETE","is_grantable":false},{"owner_name":"supabase_admin","schema_name":"public","object_type":"r","grantee":"service_role","grantor":"supabase_admin","privilege_type":"INSERT","is_grantable":false},{"owner_name":"supabase_admin","schema_name":"public","object_type":"r","grantee":"service_role","grantor":"supabase_admin","privilege_type":"MAINTAIN","is_grantable":false},{"owner_name":"supabase_admin","schema_name":"public","object_type":"r","grantee":"service_role","grantor":"supabase_admin","privilege_type":"REFERENCES","is_grantable":false},{"owner_name":"supabase_admin","schema_name":"public","object_type":"r","grantee":"service_role","grantor":"supabase_admin","privilege_type":"SELECT","is_grantable":false},{"owner_name":"supabase_admin","schema_name":"public","object_type":"r","grantee":"service_role","grantor":"supabase_admin","privilege_type":"TRIGGER","is_grantable":false},{"owner_name":"supabase_admin","schema_name":"public","object_type":"r","grantee":"service_role","grantor":"supabase_admin","privilege_type":"TRUNCATE","is_grantable":false},{"owner_name":"supabase_admin","schema_name":"public","object_type":"r","grantee":"service_role","grantor":"supabase_admin","privilege_type":"UPDATE","is_grantable":false}]$existing_defaults$::jsonb THEN
  RAISE EXCEPTION 'Exact existing existing API defaults differ';END IF;
 IF (SELECT count(*) FROM q310_expected_relations)<>240 OR
    (SELECT count(*) FROM q310_expected_relations WHERE needs_update)<>238 OR
    EXISTS(SELECT 1 FROM q310_expected_relations WHERE needs_update IS DISTINCT FROM (old_sha256<>new_sha256)) THEN
  RAISE EXCEPTION 'Exact 240-relation correspondence required';END IF;
 IF EXISTS(SELECT object_identity FROM public.custodial_release_authority_restore_inventory WHERE object_kind='relation'
  EXCEPT SELECT identity FROM q310_expected_relations) OR EXISTS(
  SELECT identity FROM q310_expected_relations EXCEPT SELECT object_identity FROM public.custodial_release_authority_restore_inventory WHERE object_kind='relation') THEN
  RAISE EXCEPTION 'Captured relation identity set differs';END IF;
 IF (SELECT count(*) FROM public.custodial_release_authority_restore_inventory i
  WHERE CASE WHEN i.object_kind='function' THEN to_regprocedure(i.object_identity)='public.custodial_release_authority_current_relation_definition(text)'::regprocedure ELSE false END)<>1 OR
  NOT EXISTS(SELECT 1 FROM public.custodial_release_authority_restore_inventory WHERE object_kind='function'
   AND object_identity='custodial_release_authority_current_relation_definition(text)' AND restore_order=100065
   AND definition_sha256='a9f77828c5917b95f5dea85ee46bed6ef6581e203cb468a7f15647b59fd7f125' AND public.static_weekly_digest_text(definition_sql)='a9f77828c5917b95f5dea85ee46bed6ef6581e203cb468a7f15647b59fd7f125') THEN
  RAISE EXCEPTION 'Original renderer inventory alias differs';END IF;
 FOR obj IN SELECT * FROM q310_expected_relations ORDER BY identity COLLATE "C" LOOP
  relation_oid:=to_regclass(obj.identity);
  IF relation_oid IS NULL OR NOT EXISTS(SELECT 1 FROM pg_class WHERE oid=relation_oid AND relkind IN('r','p') AND NOT relispartition) THEN
   RAISE EXCEPTION 'Original captured relation missing or unsupported: %',obj.identity;END IF;
  EXECUTE format('LOCK TABLE %s IN ACCESS SHARE MODE',relation_oid::regclass);
  SELECT array_agg(a.attname::text ORDER BY a.attnum),array_agg(a.attnum::integer ORDER BY a.attnum),bool_or(a.attisdropped)
  INTO names,ordinals,dropped FROM pg_attribute a WHERE a.attrelid=relation_oid AND a.attnum>0;
  IF dropped IS DISTINCT FROM false OR names IS DISTINCT FROM obj.columns_in_order OR
   ordinals IS DISTINCT FROM ARRAY(SELECT generate_series(1,cardinality(obj.columns_in_order))) THEN
   RAISE EXCEPTION 'Unproven live physical order or ordinal gap: %',obj.identity;END IF;
  IF public.static_weekly_digest_text(public.custodial_release_authority_current_relation_definition(obj.identity)) IS DISTINCT FROM obj.old_sha256 OR
   NOT EXISTS(SELECT 1 FROM public.custodial_release_authority_restore_inventory i WHERE i.object_kind='relation'
    AND i.object_identity=obj.identity AND i.restore_order=obj.restore_order AND i.definition_sha256=obj.old_sha256
    AND public.static_weekly_digest_text(i.definition_sql)=obj.old_sha256
    AND i.definition_sql=public.custodial_release_authority_current_relation_definition(obj.identity)) THEN
   RAISE EXCEPTION 'Exact original relation source or stored tuple differs: %',obj.identity;END IF;
 END LOOP;
END $predecessor$;
CREATE TEMP TABLE q310_inventory_before ON COMMIT DROP AS TABLE public.custodial_release_authority_restore_inventory;
CREATE TEMP TABLE q310_surface_before ON COMMIT DROP AS SELECT * FROM public.custodial_release_canary_authority_surface();
CREATE TEMP TABLE q310_renderer_before ON COMMIT DROP AS
 SELECT p.* FROM pg_proc p WHERE p.oid='public.custodial_release_authority_current_relation_definition(text)'::regprocedure;
CREATE TEMP TABLE q310_relation_before ON COMMIT DROP AS
 SELECT c.oid,c.relowner,c.relacl,c.relkind,c.relpersistence,c.relrowsecurity,c.relforcerowsecurity,c.relispartition
 FROM pg_class c WHERE c.oid IN(SELECT to_regclass(identity) FROM q310_expected_relations)
 OR c.oid='public.custodial_release_authority_restore_inventory'::regclass;
CREATE TEMP TABLE q310_attributes_before ON COMMIT DROP AS
 SELECT to_jsonb(a) AS attribute_tuple FROM pg_attribute a JOIN q310_relation_before b ON b.oid=a.attrelid WHERE a.attnum>0;
CREATE TEMP TABLE q310_triggers_before ON COMMIT DROP AS
 SELECT to_jsonb(t) AS trigger_tuple FROM pg_trigger t JOIN q310_relation_before b ON b.oid=t.tgrelid;
CREATE TEMP TABLE q310_defaults_before ON COMMIT DROP AS TABLE pg_default_acl;
CREATE TEMP TABLE q310_updates(kind text NOT NULL,identity text NOT NULL,definition text NOT NULL,sha256 text NOT NULL,PRIMARY KEY(kind,identity)) ON COMMIT DROP;
DO $binding$
DECLARE prior text; revised text; actual text; changed integer;
BEGIN
 prior:=pg_get_functiondef('public.custodial_release_authority_current_relation_definition(text)'::regprocedure);
 IF public.static_weekly_digest_text(prior) IS DISTINCT FROM 'a9f77828c5917b95f5dea85ee46bed6ef6581e203cb468a7f15647b59fd7f125' THEN
  RAISE EXCEPTION 'Old renderer changed after predecessor check';END IF;
 revised:=replace(prior,$needle$E',\n  ' order by a.attname$needle$,$needle$E',\n  ' order by a.attnum$needle$);
 IF public.static_weekly_digest_text(revised) IS DISTINCT FROM '11e37500c91e07715543c4f15cdcc221b7a1764c32153cc6086ce2a6137214b5' THEN
  RAISE EXCEPTION 'Renderer change is not the exact reviewed ordinal-order substitution';END IF;
 EXECUTE revised;
 IF public.static_weekly_digest_text(pg_get_functiondef('public.custodial_release_authority_current_relation_definition(text)'::regprocedure))
  IS DISTINCT FROM '11e37500c91e07715543c4f15cdcc221b7a1764c32153cc6086ce2a6137214b5' THEN RAISE EXCEPTION 'Changed renderer readback differs';END IF;
 IF EXISTS(SELECT 1 FROM q310_expected_relations e
  WHERE public.static_weekly_digest_text(public.custodial_release_authority_current_relation_definition(e.identity)) IS DISTINCT FROM e.new_sha256) THEN
  RAISE EXCEPTION 'Reordered relation DDL differs from exact correspondence';END IF;
 SELECT 'relation',e.identity,public.custodial_release_authority_current_relation_definition(e.identity),e.new_sha256
 FROM q310_expected_relations e WHERE e.needs_update;
  pg_get_functiondef('public.custodial_release_authority_current_relation_definition(text)'::regprocedure),'11e37500c91e07715543c4f15cdcc221b7a1764c32153cc6086ce2a6137214b5');
 IF (SELECT count(*) FROM q310_updates)<>239 THEN RAISE EXCEPTION 'Exact changed-tuple count differs';END IF;
 ALTER TABLE public.custodial_release_authority_restore_inventory DISABLE TRIGGER trg_custodial_release_authority_restore_inventory_immutable;
 UPDATE public.custodial_release_authority_restore_inventory i SET definition_sql=u.definition,
  definition_sha256=u.sha256,captured_at=statement_timestamp() FROM q310_updates u
  WHERE i.object_kind=u.kind AND i.object_identity=u.identity;
 GET DIAGNOSTICS changed=ROW_COUNT;
 IF changed<>239 THEN RAISE EXCEPTION 'Expected 239 existing inventory tuple updates, observed %',changed;END IF;
 ALTER TABLE public.custodial_release_authority_restore_inventory ENABLE ALWAYS TRIGGER trg_custodial_release_authority_restore_inventory_immutable;
 IF EXISTS(SELECT 1 FROM q310_updates u LEFT JOIN public.custodial_release_authority_restore_inventory i
  ON i.object_kind=u.kind AND i.object_identity=u.identity WHERE i.inventory_id IS NULL OR i.definition_sql IS DISTINCT FROM u.definition
  OR i.definition_sha256 IS DISTINCT FROM u.sha256 OR public.static_weekly_digest_text(i.definition_sql) IS DISTINCT FROM u.sha256) THEN
  RAISE EXCEPTION 'Changed inventory tuple readback differs';END IF;
 SELECT public.static_weekly_digest_text(string_agg(restore_order::text||E'\n'||object_kind||E'\n'||object_identity||E'\n'||definition_sha256||E'\n'||public.static_weekly_digest_text(definition_sql),E'\n---\n' ORDER BY object_kind COLLATE "C",object_identity COLLATE "C"))
 INTO actual FROM public.custodial_release_authority_restore_inventory;
 IF actual IS DISTINCT FROM '0213f2b256bcac7b8db623758ef26807583ea27074a7c362af259122d4275dca' THEN RAISE EXCEPTION 'Exact derived post-binding inventory aggregate differs';END IF;
 IF EXISTS(SELECT b.* FROM q310_inventory_before b WHERE NOT EXISTS(SELECT 1 FROM q310_updates u WHERE u.kind=b.object_kind AND u.identity=b.object_identity)
  EXCEPT SELECT * FROM public.custodial_release_authority_restore_inventory) OR EXISTS(
  SELECT i.* FROM public.custodial_release_authority_restore_inventory i WHERE NOT EXISTS(SELECT 1 FROM q310_updates u WHERE u.kind=i.object_kind AND u.identity=i.object_identity)
  EXCEPT SELECT * FROM q310_inventory_before) THEN RAISE EXCEPTION 'Unrelated inventory row changed';END IF;
 IF EXISTS(SELECT 1 FROM q310_inventory_before b FULL JOIN public.custodial_release_authority_restore_inventory i USING(object_kind,object_identity)
  WHERE (to_jsonb(b)-ARRAY['definition_sql','definition_sha256','captured_at']) IS DISTINCT FROM
        (to_jsonb(i)-ARRAY['definition_sql','definition_sha256','captured_at'])) THEN
  RAISE EXCEPTION 'Inventory identity, restore order, alias or other metadata changed';END IF;
 IF EXISTS(SELECT * FROM q310_surface_before EXCEPT SELECT * FROM public.custodial_release_canary_authority_surface()) OR EXISTS(
  SELECT * FROM public.custodial_release_canary_authority_surface() EXCEPT SELECT * FROM q310_surface_before) OR
  public.static_weekly_digest_text(pg_get_functiondef('public.custodial_release_canary_authority_surface()'::regprocedure)) IS DISTINCT FROM '55fe3e609c8a145f946602c6fbf16df4aa1eab410f50e048b778e7f4bfe72b33' THEN
  RAISE EXCEPTION 'Original canary surface changed';END IF;
 IF EXISTS(SELECT 1 FROM q310_renderer_before b LEFT JOIN pg_proc p ON p.oid=b.oid
  WHERE (to_jsonb(b)-'prosrc') IS DISTINCT FROM (to_jsonb(p)-'prosrc')) THEN
  RAISE EXCEPTION 'Renderer owner, ACL, identity or non-body property changed';END IF;
 IF EXISTS(SELECT 1 FROM q310_relation_before b LEFT JOIN pg_class c ON c.oid=b.oid
  WHERE c.oid IS NULL OR ROW(b.relowner,b.relacl,b.relkind,b.relpersistence,b.relrowsecurity,b.relforcerowsecurity,b.relispartition)
   IS DISTINCT FROM ROW(c.relowner,c.relacl,c.relkind,c.relpersistence,c.relrowsecurity,c.relforcerowsecurity,c.relispartition)) THEN
  RAISE EXCEPTION 'Original relation owner, ACL or state changed';END IF;
 IF EXISTS(SELECT * FROM q310_attributes_before EXCEPT SELECT to_jsonb(a) AS attribute_tuple FROM pg_attribute a JOIN q310_relation_before b ON b.oid=a.attrelid WHERE a.attnum>0) OR EXISTS(
  SELECT to_jsonb(a) AS attribute_tuple FROM pg_attribute a JOIN q310_relation_before b ON b.oid=a.attrelid WHERE a.attnum>0 EXCEPT SELECT * FROM q310_attributes_before) THEN
  RAISE EXCEPTION 'Original physical column tuple changed';END IF;
 IF EXISTS(SELECT * FROM q310_triggers_before EXCEPT SELECT to_jsonb(t) AS trigger_tuple FROM pg_trigger t JOIN q310_relation_before b ON b.oid=t.tgrelid) OR EXISTS(
  SELECT to_jsonb(t) AS trigger_tuple FROM pg_trigger t JOIN q310_relation_before b ON b.oid=t.tgrelid EXCEPT SELECT * FROM q310_triggers_before) THEN
  RAISE EXCEPTION 'Original trigger definition or enabled state changed';END IF;
 IF EXISTS(SELECT * FROM q310_defaults_before EXCEPT SELECT * FROM pg_default_acl) OR EXISTS(
  SELECT * FROM pg_default_acl EXCEPT SELECT * FROM q310_defaults_before) THEN RAISE EXCEPTION 'Original default privileges changed';END IF;
 IF (SELECT tgenabled FROM pg_trigger WHERE tgrelid='public.custodial_release_authority_restore_inventory'::regclass
  AND tgname='trg_custodial_release_authority_restore_inventory_immutable') IS DISTINCT FROM 'A' THEN RAISE EXCEPTION 'ALWAYS recovery guard lost';END IF;
END $binding$;
COMMIT;
